import{_ as a,o,c as e,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"TTS 做双人对白：音色、停顿与批量","description":"","frontmatter":{"title":"TTS 做双人对白：音色、停顿与批量"},"headers":[],"relativePath":"md/ai-content/tts.md","filePath":"md/ai-content/tts.md","lastUpdated":1795424423000}'),l={name:"md/ai-content/tts.md"};function i(n,t,s,h,d,u){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="tts-做双人对白-音色、停顿与批量" tabindex="-1">TTS 做双人对白：音色、停顿与批量 <a class="header-anchor" href="#tts-做双人对白-音色、停顿与批量" aria-label="Permalink to &quot;TTS 做双人对白：音色、停顿与批量&quot;">​</a></h1><p>双人对白的短视频，难点不在&quot;能不能生成语音&quot;，而在<strong>让两个声音像两个人在说话</strong>。一段对白听起来假，通常不是音质问题，而是节奏问题。</p><h2 id="音色的选择逻辑" tabindex="-1">音色的选择逻辑 <a class="header-anchor" href="#音色的选择逻辑" aria-label="Permalink to &quot;音色的选择逻辑&quot;">​</a></h2><p>两个音色要满足三个条件：</p><ol><li><strong>音高差明显</strong> —— 两个声音的基频区间要错开，否则听众分不清角色</li><li><strong>语速差合理</strong> —— 一个人稍快、一个人稍慢，对话才有推进感</li><li><strong>音色气质跟人物一致</strong> —— 尖锐对沉稳、话痨对冷淡，人设有对立才有张力</li></ol><p>实践中，男女对最容易分辨；同性别对白要靠音高和语速拉开差距，否则听众要靠字幕区分角色，观感会明显下降。</p><h2 id="停顿是-像人-的关键" tabindex="-1">停顿是&quot;像人&quot;的关键 <a class="header-anchor" href="#停顿是-像人-的关键" aria-label="Permalink to &quot;停顿是&quot;像人&quot;的关键&quot;">​</a></h2><p>机器合成的通病是停顿太均匀。真人说话的停顿有几种性质完全不同的类型：</p><ul><li><strong>换气停顿</strong>：长句中间，100~200ms</li><li><strong>语义停顿</strong>：说完一层意思，300~500ms</li><li><strong>对话间隙</strong>：两个人交替发言之间，500~800ms</li><li><strong>情绪停顿</strong>：故意卡住制造张力，800ms 以上</li></ul><p>如果只用模型的默认停顿，四种都变成差不多长度，听起来就是朗读而不是对话。</p><p>可用的做法是<strong>在不该停顿的地方插标记、在该停顿的地方显式拼接静音</strong>：按句生成音频，句子之间按语义插入不同长度的空白，而不是指望一次整段生成自动做对。</p><h2 id="批量生成的三条约定" tabindex="-1">批量生成的三条约定 <a class="header-anchor" href="#批量生成的三条约定" aria-label="Permalink to &quot;批量生成的三条约定&quot;">​</a></h2><h3 id="_1-文本先规范化" tabindex="-1">1. 文本先规范化 <a class="header-anchor" href="#_1-文本先规范化" aria-label="Permalink to &quot;1. 文本先规范化&quot;">​</a></h3><p>生成前统一处理：数字转中文读法、英文缩写按读音展开、括号与符号去掉、长句切成 15~25 字的短句。这些不处理，错误率会集中在数字和符号上——而这两类恰恰是最容易被听众抓到的。</p><h3 id="_2-按切分单元缓存" tabindex="-1">2. 按切分单元缓存 <a class="header-anchor" href="#_2-按切分单元缓存" aria-label="Permalink to &quot;2. 按切分单元缓存&quot;">​</a></h3><p>一行台词 = 一个音频文件 + 一份参数记录。改名、改标点不影响已生成的部分，只有真正改了字的行才重新生成。批量场景下这一个设计能把重跑成本砍掉一大半。</p><h3 id="_3-拼接时统一采样率和响度" tabindex="-1">3. 拼接时统一采样率和响度 <a class="header-anchor" href="#_3-拼接时统一采样率和响度" aria-label="Permalink to &quot;3. 拼接时统一采样率和响度&quot;">​</a></h3><p>不同批次生成的音频，采样率、响度可能不一致。拼接前统一转成同一规格，并做响度归一化，否则成品会出现&quot;某几句突然变大变小&quot;。</p><h2 id="什么时候不该用-tts" tabindex="-1">什么时候不该用 TTS <a class="header-anchor" href="#什么时候不该用-tts" aria-label="Permalink to &quot;什么时候不该用 TTS&quot;">​</a></h2><ul><li>需要极强情绪表现的内容（拟声、气声、笑），合成痕迹明显</li><li>需要口型同步的真人出镜视频</li><li>对版权声音有明确要求时（商用场景要确认音色授权范围）</li></ul><p>做&quot;观点口播&quot;和&quot;双人对白&quot;这类以信息为主的内容，TTS 已经完全够用——观众在意的是内容是否说得清楚，不是声音是否完美。</p>',21)])])}const q=a(l,[["render",i]]);export{p as __pageData,q as default};
